From 90db1582a97d048769198ee1c0f367d003eeb130 Mon Sep 17 00:00:00 2001
From: Yu Watanabe <watanabe.yu+github@gmail.com>
Date: Wed, 24 Apr 2024 14:58:07 +0900
Subject: [PATCH] run/run: fix invocation ID handling

Fixes a regression introduced by 8157cc0e3e33c97b406cc088cf001ca524154f64.

diff --git a/src/shared/bus-util.c b/src/shared/bus-util.c
index 9a480aa0e3..dfe8b60ecd 100644
--- a/src/shared/bus-util.c
+++ b/src/shared/bus-util.c
@@ -914,16 +914,15 @@ int bus_message_read_id128(sd_bus_message *m, sd_id128_t *ret) {
         case 0:
                 if (ret)
                         *ret = SD_ID128_NULL;
-                break;
+                return 0;

         case sizeof(sd_id128_t):
                 if (ret)
                         memcpy(ret, a, sz);
-                break;
+                return !memeqzero(a, sz); /* This intends to sd_id128_is_null(), but ret may be NULL, so
+                                           * let'suse memeqzero() here. */

         default:
                 return -EINVAL;
         }
-
-        return 0;
 }
-- 
