Here is the commit message:
run/run: fix invocation ID handling

Fixes a regression introduced by 8157cc0e3e33c97b406cc088cf001ca524154f64.

Here is the root cause:
The bug was caused by incorrect return value handling in the `acquire_invocation_id` function in `src/run/run.c`, which always returned zero instead of the actual result of the operation. This led to a failure in correctly indicating whether a non-null invocation ID was acquired, resulting in a regression in invocation ID handling.

Here is the patch:

 static int acquire_invocation_id(sd_bus *bus, const char *unit, sd_id128_t *ret) {
         _cleanup_(sd_bus_error_free) sd_bus_error error = SD_BUS_ERROR_NULL;
         _cleanup_(sd_bus_message_unrefp) sd_bus_message *reply = NULL;
         _cleanup_free_ char *object = NULL;
         int r;

         assert(bus);
         assert(ret);

         if (unit) {
                 object = unit_dbus_path_from_name(unit);
                 if (!object)
                         return log_oom();
         }

         r = sd_bus_get_property(bus,
                                 "org.freedesktop.systemd1",
                                 object ?: "/org/freedesktop/systemd1/unit/self",
                                 "org.freedesktop.systemd1.Unit",
                                 "InvocationID",
                                 &error,
                                 &reply,
                                 "ay");
         if (r < 0)
                 return log_error_errno(r, "Failed to request invocation ID for unit: %s", bus_error_message(&error, r));

         r = bus_message_read_id128(reply, ret);
         if (r < 0)
                 return bus_log_parse_error(r);

-        return 0;
+        return r; /* Return true when we get a non-null invocation ID. */
 }



